fields.InputDefinition:
{
  "goal": "Open an entity whose records contain a large code, SQL, JSON, or markdown field via the LEFT sidebar 'Search entities...' box — good candidates are 'Templates' (template text), 'MJ: Queries' (SQL), or 'Email Templates'. Click a row and 'Open Full Record'. Locate the long code/markdown field: in read mode it should render in a formatted way (syntax-highlighted code block or rendered markdown, NOT a single plain input line). Then click Edit and confirm that field becomes a multi-line code editor (syntax-highlighted textarea) rather than a one-line text box. Success is the long/code field using the rich code-editor rendering in at least one mode. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "A long code/SQL/JSON/markdown field renders with rich formatting (syntax-highlighted code editor or rendered markdown), not a plain single-line input",
    "In edit mode the field presents as a multi-line code/rich editor",
    "No error messages, blank screens, or crash pages"
  ]
}
